namespace AireCast.Core.FairPlay;

/// <summary>
/// Tablas white-box de FairPlay SAP, generadas desde fairplay_tables.py (doubletake, LGPL-3.0-or-later).
/// No editar a mano. Cada red son 9x16 sustituciones, 4x4 mezclas y 16 finales: (tabla, xor entrada, xor salida).
/// </summary>
internal static class FairPlayTables
{
    private const int RefLength = 3;

    internal static readonly byte[] FirstInputMask = Convert.FromHexString(FirstInputMaskHex);
    internal static readonly byte[] SecondOutputMask = Convert.FromHexString(SecondOutputMaskHex);
    internal static readonly byte[][] SubstitutionBases = Rows(SubstitutionBasesHex);
    internal static readonly byte[][] MixBases = Rows(MixBasesHex);
    internal static readonly NetworkTables First = new(Convert.FromHexString(FirstTablesHex));
    internal static readonly NetworkTables Second = new(Convert.FromHexString(SecondTablesHex));

    private static byte[][] Rows(string hex) => Convert.FromHexString(hex).Chunk(256).ToArray();

    internal sealed class NetworkTables(byte[] data)
    {
        private const int MixOffset = 9 * 16;
        private const int FinalOffset = MixOffset + 4 * 4;

        internal int Round(int bank, int index, int value) => Lookup(bank * 16 + index, value, SubstitutionBases);

        internal int Mix(int input, int output, int value) => Lookup(MixOffset + input * 4 + output, value, MixBases);

        internal int Final(int index, int value) => Lookup(FinalOffset + index, value, SubstitutionBases);

        private int Lookup(int entry, int value, byte[][] bases)
        {
            int at = entry * RefLength;
            return bases[data[at]][value ^ data[at + 1]] ^ data[at + 2];
        }
    }

    private const string FirstInputMaskHex =
        "a09675fafe91ea7be48a79df6e71dd17";
    private const string SecondOutputMaskHex =
        "67bc54c08e32851b50d2125f68b740a5";
    private const string SubstitutionBasesHex =
        "";
    private const string MixBasesHex =
        "";
    private const string FirstTablesHex =
        "";
    private const string SecondTablesHex =
        "";
}
